#include <USB.h>
#include <USBHID.h>

// Создаем объект клавиатуры
USBHIDKeyboard keyboard;

void setup() {
  // Инициализация USB
  USBDevice.begin();

  // Задержка для инициализации
  delay(1000);

  Serial.begin(115200);
  Serial.println("ESP32-S3 Keyboard Emulator Started");

  // Включаем NumLock (отправляем пакет с состоянием модификаторов)
  // 0x02 = NumLock включен
  keyboard.sendKeyReport(0x02, 0, 0, 0, 0, 0, 0, 0);
  delay(100);
  keyboard.sendKeyReport(0, 0, 0, 0, 0, 0, 0, 0); // Сброс

  Serial.println("NumLock включен");

  // Задержка перед началом печати
  delay(2000);

  // Начинаем печать команд
  typeCommand();
}

void loop() {
  // Пустой цикл
}

void typeCommand() {
  Serial.println("Печать команды...");

  // 1. Открываем "Выполнить" (Win + R)
  // Используем константы из USBHID.h
  keyboard.sendKeyReport(HID_KEY_LEFT_GUI, HID_KEY_R, 0, 0, 0, 0, 0, 0);
  delay(100);
  keyboard.sendKeyReport(0, 0, 0, 0, 0, 0, 0, 0);
  delay(500);

  // 2. Пишем "cmd"
  writeString("cmd");
  delay(200);

  // 3. Нажимаем Enter
  keyboard.sendKeyReport(0, HID_KEY_RETURN, 0, 0, 0, 0, 0, 0);
  delay(500);

  // 4. Разворачиваем на весь экран (Alt + Space, затем X)
  keyboard.sendKeyReport(HID_KEY_LEFT_ALT, HID_KEY_SPACE, 0, 0, 0, 0, 0, 0);
  delay(100);
  keyboard.sendKeyReport(0, 0, 0, 0, 0, 0, 0, 0);
  delay(200);

  // Нажимаем 'X' для разворачивания
  keyboard.sendKeyReport(0, HID_KEY_X, 0, 0, 0, 0, 0, 0);
  delay(100);
  keyboard.sendKeyReport(0, 0, 0, 0, 0, 0, 0, 0);
  delay(500);

  // 5. Пишем "color 2"
  writeString("color 2");
  delay(200);

  // 6. Нажимаем Enter
  keyboard.sendKeyReport(0, HID_KEY_RETURN, 0, 0, 0, 0, 0, 0);
  delay(500);

  // 7. Пишем "dir/s"
  writeString("dir/s");
  delay(200);

  // 8. Нажимаем Enter
  keyboard.sendKeyReport(0, HID_KEY_RETURN, 0, 0, 0, 0, 0, 0);

  Serial.println("Команда выполнена");
}

void writeString(const char* str) {
  for (int i = 0; i < strlen(str); i++) {
    keyboard.write(str[i]);
    delay(10); // Небольшая задержка между символами для надежности
  }
}
